import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Sources","description":"","frontmatter":{"title":"Sources"},"headers":[],"relativePath":"docs/concepts/sources.md","filePath":"docs/concepts/sources.md","lastUpdated":1790449305000}'),s={name:"docs/concepts/sources.md"};function n(i,e,c,d,l,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h1><p>A <strong>source</strong> is a file (or set of files) that feeds data into a project — a bank statement, a brokerage statement, a spreadsheet export, or a general document. A project can have as many sources as you like; the <a href="/docs/getting-started/add-first-source">Add your first source</a> page covers adding one.</p><h2 id="managing-sources" tabindex="-1">Managing sources <a class="header-anchor" href="#managing-sources" aria-label="Permalink to &quot;Managing sources&quot;">​</a></h2><p>The Sources view for a project lists everything that&#39;s been added, with a few actions available on each:</p><ul><li><strong>Relocate</strong> — point a source at a new file or folder location, for example if the original file moved on disk.</li><li><strong>Rescan</strong> — re-run parsing on the existing file in place, useful after a parser has been fixed or improved.</li><li><strong>Remove</strong> — take a source (and its data) out of the project.</li></ul><h2 id="when-a-format-isn-t-recognized" tabindex="-1">When a format isn&#39;t recognized <a class="header-anchor" href="#when-a-format-isn-t-recognized" aria-label="Permalink to &quot;When a format isn&#39;t recognized&quot;">​</a></h2><p>If a file doesn&#39;t match any known statement format, OrbySystems doesn&#39;t reject it — it&#39;s simply treated as a general document, so you can still chat over its contents. If you want a format properly recognized (with transactions parsed out, categorized, and so on), see the <a href="/docs/tools/transactions-extractor-builder">Transactions Extractor Builder</a>.</p>',7)])])}const p=a(s,[["render",n]]);export{h as __pageData,p as default};
